import React, { useState, useMemo, useEffect } from "react";
import {
  Search, Bell, ChevronDown, ChevronLeft, ChevronRight, Phone, Mail,
  MessageCircle, Eye, Plus, X, Download, ArrowUpDown, LayoutGrid, List as ListIcon,
} from "lucide-react";

/* ---------------------------------------------------------------------- */
/* Reference "today" so the dataset reads consistently                     */
const TODAY = new Date(2026, 7, 27); // 27 Aug 2026
const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const MONTH_SHORT = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

function parseDob(dob) {
  const [y, m, d] = dob.split("-").map(Number);
  return { year: y, month: m, day: d };
}
function daysUntilBirthday(dob, ref = TODAY) {
  const { month, day } = parseDob(dob);
  const refMid = new Date(ref.getFullYear(), ref.getMonth(), ref.getDate());
  let next = new Date(refMid.getFullYear(), month - 1, day);
  if (next < refMid) next = new Date(refMid.getFullYear() + 1, month - 1, day);
  return Math.round((next - refMid) / 86400000);
}
function currentAge(dob, ref = TODAY) {
  const { year, month, day } = parseDob(dob);
  let age = ref.getFullYear() - year;
  const hasHad = ref.getMonth() + 1 > month || (ref.getMonth() + 1 === month && ref.getDate() >= day);
  if (!hasHad) age -= 1;
  return age;
}
function turningAge(dob, ref = TODAY) { return currentAge(dob, ref) + 1; }
function formatBirthday(dob) {
  const { month, day } = parseDob(dob);
  return `${MONTH_SHORT[month - 1]} ${day}`;
}
function initials(name) {
  return name.split(" ").map((p) => p[0]).slice(0, 2).join("").toUpperCase();
}

/* ---------------------------------------------------------------------- */
/* Seed data                                                                */
const WHATSAPP_TEMPLATE = (name) =>
  `Dear ${name},\n\nWishing you a very Happy Birthday from Oranz Body Spa.\nMay your year be filled with happiness, good health, relaxation, and success.\n\nThank you for being a valued client.\n\nWarm Regards,\nOranz Body Spa`;

const LOGO_DATA_URI = "data:image/png;base64,";

/* ---------------------------------------------------------------------- */
export default function App() {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("overview");
  const [branch, setBranch] = useState("All Branches");
  const [globalSearch, setGlobalSearch] = useState("");
  const [notifOpen, setNotifOpen] = useState(false);
  const [toast, setToast] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [monthCursor, setMonthCursor] = useState(new Date(2026, 7, 1));
  const [calSelectedDay, setCalSelectedDay] = useState(null);
  const [calListView, setCalListView] = useState(false);
  const [sortAsc, setSortAsc] = useState(true);

  const [tableSearch, setTableSearch] = useState("");
  const [filterMembership, setFilterMembership] = useState("All");
  const [filterVip, setFilterVip] = useState("All");
  const [filterMonth, setFilterMonth] = useState("All");

  function mapRow(row) {
    return {
      id: row.id,
      clientCode: row.client_code,
      name: row.name,
      phone: row.phone,
      whatsapp: row.whatsapp,
      email: row.email,
      dob: row.dob,
      gender: row.gender,
      city: row.city,
      membership: row.membership,
      branch: row.branch,
      lastVisit: row.last_visit || "—",
      status: row.status,
      vip: row.vip,
      anniversary: row.anniversary,
      notes: row.notes,
    };
  }

  async function fetchClients() {
    try {
      const res = await fetch("/api/clients");
      if (!res.ok) throw new Error("Failed to load clients");
      const data = await res.json();
      setClients(data.map(mapRow));
    } catch (e) {
      showToast("Could not load clients — check your Supabase connection");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    fetchClients();
  }, []);

  function handleSendWhatsApp(c) {
    // Manual send: opens WhatsApp with the message pre-typed. You still press Send yourself.
    const rawNumber = (c.whatsapp || c.phone || "").replace(/[^0-9]/g, "");
    if (!rawNumber) { showToast(`${c.name} ke liye WhatsApp number nahi mila`); return; }
    const message = `Dear ${c.name},\n\nWishing you a very Happy Birthday from Oranz Body Spa.\nMay your year be filled with happiness, good health, relaxation, and success.\n\nThank you for being a valued client.\n\nWarm Regards,\nOranz Body Spa`;
    const url = `https://wa.me/${rawNumber}?text=${encodeURIComponent(message)}`;
    window.open(url, "_blank");
  }

  function showToast(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 2600);
  }

  const withMeta = useMemo(
    () =>
      clients.map((c) => ({
        ...c,
        age: currentAge(c.dob),
        turning: turningAge(c.dob),
        days: daysUntilBirthday(c.dob),
        bday: formatBirthday(c.dob),
      })),
    [clients]
  );

  const branchFiltered = useMemo(
    () => (branch === "All Branches" ? withMeta : withMeta.filter((c) => c.branch === branch)),
    [withMeta, branch]
  );

  const today = branchFiltered.filter((c) => c.days === 0);
  const tomorrow = branchFiltered.filter((c) => c.days === 1);
  const next3 = branchFiltered.filter((c) => c.days >= 2 && c.days <= 3);
  const thisWeek = branchFiltered.filter((c) => c.days >= 0 && c.days <= 7);
  const nextWeek = branchFiltered.filter((c) => c.days >= 8 && c.days <= 14);
  const thisMonth = branchFiltered
    .filter((c) => parseDob(c.dob).month === TODAY.getMonth() + 1 && c.days >= 0 && c.days < 31)
    .sort((a, b) => (sortAsc ? a.days - b.days : b.days - a.days));
  const vipClients = branchFiltered.filter((c) => c.vip).sort((a, b) => a.days - b.days);

  const tableClients = useMemo(() => {
    let rows = branchFiltered;
    if (tableSearch.trim()) {
      const q = tableSearch.toLowerCase();
      rows = rows.filter(
        (c) =>
          c.name.toLowerCase().includes(q) ||
          c.phone.includes(q) ||
          c.email.toLowerCase().includes(q) ||
          c.id.toLowerCase().includes(q)
      );
    }
    if (filterMembership !== "All") rows = rows.filter((c) => c.membership === filterMembership);
    if (filterVip !== "All") rows = rows.filter((c) => (filterVip === "VIP" ? c.vip : !c.vip));
    if (filterMonth !== "All") rows = rows.filter((c) => MONTH_NAMES[parseDob(c.dob).month - 1] === filterMonth);
    return rows;
  }, [branchFiltered, tableSearch, filterMembership, filterVip, filterMonth]);

  const globalHits = useMemo(() => {
    if (!globalSearch.trim()) return [];
    const q = globalSearch.toLowerCase();
    return withMeta
      .filter((c) => c.name.toLowerCase().includes(q) || c.phone.includes(q) || c.id.toLowerCase().includes(q))
      .slice(0, 6);
  }, [globalSearch, withMeta]);

  const totalClients = branchFiltered.length;

  const navItems = [
    { key: "overview", label: "Overview" },
    { key: "today", label: "Today", count: today.length },
    { key: "tomorrow", label: "Tomorrow", count: tomorrow.length },
    { key: "next3", label: "Next 3 Days", count: next3.length },
    { key: "week", label: "This Week", count: thisWeek.length },
    { key: "nextweek", label: "Next Week", count: nextWeek.length },
    { key: "month", label: "This Month", count: thisMonth.length },
    { key: "vip", label: "VIP Clients", count: vipClients.length },
    { key: "clients", label: "All Clients" },
    { key: "calendar", label: "Calendar" },
    { key: "reports", label: "Reports" },
  ];

  function ActionIcons({ c }) {
    return (
      <div className="action-row">
        <button className="icon-btn" title="View Profile" onClick={() => showToast(`Opening profile — ${c.name}`)}>
          <Eye size={15} />
        </button>
        <button
          className="icon-btn"
          title="WhatsApp Wish"
          onClick={() => handleSendWhatsApp(c)}
        >
          <MessageCircle size={15} />
        </button>
        <button className="icon-btn" title="Email Wish" onClick={() => showToast(`Birthday email sent to ${c.name}`)}>
          <Mail size={15} />
        </button>
        <button className="icon-btn" title="Call Client" onClick={() => showToast(`Calling ${c.name}…`)}>
          <Phone size={15} />
        </button>
      </div>
    );
  }

  function VipBadge() {
    return <span className="vip-badge">VIP</span>;
  }

  function MembershipTag({ level }) {
    return <span className={`tag tag-${level.toLowerCase()}`}>{level}</span>;
  }

  function StatusTag({ status }) {
    return <span className={`status-dot status-${status.toLowerCase()}`}>{status}</span>;
  }

  function RowWrap({ c, children }) {
    return <tr className={c.vip ? "vip-row" : ""}>{children}</tr>;
  }

  /* ---- section renderers ---- */
  function KPICard({ label, value, accent, pulse, bold, onClick }) {
    return (
      <button
        className={`kpi-card ${pulse ? "kpi-pulse" : ""} ${bold ? "kpi-bold" : ""} ${onClick ? "kpi-clickable" : ""}`}
        style={accent ? { borderTopColor: accent, ...(bold ? { borderColor: accent } : {}) } : undefined}
        onClick={onClick}
      >
        {pulse && <span className="kpi-live-dot" style={{ background: accent }} />}
        <div className="kpi-value" style={accent ? { color: accent } : undefined}>{value}</div>
        <div className="kpi-label" style={bold ? { fontWeight: 600, color: "var(--text)" } : undefined}>{label}</div>
      </button>
    );
  }

  function TableShell({ title, subtitle, empty, children }) {
    return (
      <div className="panel">
        <div className="panel-head">
          <div>
            <h2>{title}</h2>
            {subtitle && <p className="panel-sub">{subtitle}</p>}
          </div>
        </div>
        {children ? (
          <div className="table-scroll">{children}</div>
        ) : (
          <div className="empty-state">{empty}</div>
        )}
      </div>
    );
  }

  function renderOverview() {
    return (
      <>
        <div className="kpi-grid">
          <KPICard label="Total Clients" value={totalClients} accent="#2B2B2B" onClick={() => setView("clients")} />
          <KPICard label="Today's Birthdays" value={today.length} accent="#D46A4A" pulse={today.length > 0} bold={today.length > 0} onClick={() => setView("today")} />
          <KPICard label="Tomorrow's Birthdays" value={tomorrow.length} accent="#4A7C59" pulse={tomorrow.length > 0} bold={tomorrow.length > 0} onClick={() => setView("tomorrow")} />
          <KPICard label="This Week's Birthdays" value={thisWeek.length} accent="#C89B5E" onClick={() => setView("week")} />
          <KPICard label="Next Week's Birthdays" value={nextWeek.length} accent="#B5651D" onClick={() => setView("nextweek")} />
        </div>

        <div className="quick-actions">
          <button className="btn btn-gold" onClick={() => setModalOpen(true)}>
            <Plus size={15} /> Add Client
          </button>
          <button className="btn btn-outline" onClick={() => showToast("Bulk birthday wishes queued for today's list")}>
            Send Bulk Wishes
          </button>
          <button className="btn btn-outline" onClick={() => showToast("Report export started")}>
            Export Report
          </button>
          <button className="btn btn-outline" onClick={() => setView("calendar")}>
            View Calendar
          </button>
        </div>

        {today.length > 0 ? (
          <TableShell title="Today's Birthdays" subtitle="Always shown first">
            {renderTodayTable(today)}
          </TableShell>
        ) : (
          <TableShell title="Today's Birthdays" empty="No birthdays today." />
        )}
      </>
    );
  }

  function renderTodayTable(rows) {
    return (
      <table>
        <thead>
          <tr>
            <th>Client</th><th>Age</th><th>Phone</th><th>Membership</th><th>Branch</th><th>Birthday</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td>
                <div className="client-cell">
                  <span className="avatar">{initials(c.name)}</span>
                  <span>{c.name}{c.vip && <VipBadge />}</span>
                </div>
              </td>
              <td>{c.age}</td>
              <td>{c.phone}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td>{c.branch}</td>
              <td>{c.bday}</td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  function renderTomorrowTable(rows) {
    return (
      <table>
        <thead>
          <tr><th>Client</th><th>Birthday Date</th><th>Age Turning</th><th>Phone</th><th>Membership</th><th>Actions</th></tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td><div className="client-cell"><span className="avatar">{initials(c.name)}</span><span>{c.name}{c.vip && <VipBadge />}</span></div></td>
              <td>{c.bday}</td>
              <td>Turning {c.turning}</td>
              <td>{c.phone}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  function renderDaysRemainingTable(rows) {
    return (
      <table>
        <thead>
          <tr><th>Client</th><th>Birthday Date</th><th>Days Remaining</th><th>Phone</th><th>Membership</th><th>Actions</th></tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td><div className="client-cell"><span className="avatar">{initials(c.name)}</span><span>{c.name}{c.vip && <VipBadge />}</span></div></td>
              <td>{c.bday}</td>
              <td><span className="days-badge">{c.days}</span></td>
              <td>{c.phone}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  function renderWeekTable(rows) {
    return (
      <table>
        <thead>
          <tr><th>Name</th><th>Birthday Date</th><th>Days Left</th><th>Membership</th><th>Branch</th><th>Action</th></tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td><div className="client-cell"><span className="avatar">{initials(c.name)}</span><span>{c.name}{c.vip && <VipBadge />}</span></div></td>
              <td>{c.bday}</td>
              <td><span className="days-badge">{c.days}</span></td>
              <td><MembershipTag level={c.membership} /></td>
              <td>{c.branch}</td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  function renderMonthTable(rows) {
    return (
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th className="sortable" onClick={() => setSortAsc((s) => !s)}>
              <span>Birthday Date</span> <ArrowUpDown size={12} />
            </th>
            <th>Days Left</th><th>Membership</th><th>Branch</th><th>Action</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td><div className="client-cell"><span className="avatar">{initials(c.name)}</span><span>{c.name}{c.vip && <VipBadge />}</span></div></td>
              <td>{c.bday}</td>
              <td>{c.days === 0 ? "Today" : c.days}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td>{c.branch}</td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  function renderVipTable(rows) {
    return (
      <table>
        <thead>
          <tr><th>Client</th><th>Birthday Date</th><th>Days Left</th><th>Membership</th><th>Branch</th><th>Actions</th></tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <tr className="vip-row" key={c.id}>
              <td><div className="client-cell"><span className="avatar avatar-gold">{initials(c.name)}</span><span>{c.name}<VipBadge /></span></div></td>
              <td>{c.bday}</td>
              <td>{c.days === 0 ? "Today" : c.days}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td>{c.branch}</td>
              <td><ActionIcons c={c} /></td>
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  function renderClientsTable(rows) {
    return (
      <table>
        <thead>
          <tr>
            <th>Client ID</th><th>Name</th><th>Phone</th><th>Email</th><th>DOB</th><th>Age</th>
            <th>Turning</th><th>Membership</th><th>Branch</th><th>Last Visit</th><th>Status</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((c) => (
            <RowWrap c={c} key={c.id}>
              <td className="mono">{c.clientCode}</td>
              <td><div className="client-cell"><span className="avatar">{initials(c.name)}</span><span>{c.name}{c.vip && <VipBadge />}</span></div></td>
              <td>{c.phone}</td>
              <td className="muted">{c.email}</td>
              <td>{c.bday}</td>
              <td>{c.age}</td>
              <td>{c.turning}</td>
              <td><MembershipTag level={c.membership} /></td>
              <td>{c.branch}</td>
              <td className="muted">{c.lastVisit}</td>
              <td><StatusTag status={c.status} /></td>
              <td><ActionIcons c={c} /></td>
            </RowWrap>
          ))}
        </tbody>
      </table>
    );
  }

  /* ---- calendar ---- */
  function renderCalendar() {
    const year = monthCursor.getFullYear();
    const month = monthCursor.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < firstDay; i++) cells.push(null);
    for (let d = 1; d <= daysInMonth; d++) cells.push(d);

    const dayClients = (d) =>
      branchFiltered.filter((c) => {
        const { month: m, day: dd } = parseDob(c.dob);
        return m === month + 1 && dd === d;
      });

    const isToday = (d) => year === TODAY.getFullYear() && month === TODAY.getMonth() && d === TODAY.getDate();

    return (
      <div className="panel">
        <div className="panel-head cal-head">
          <div className="cal-nav">
            <button className="icon-btn" onClick={() => setMonthCursor(new Date(year, month - 1, 1))}>
              <ChevronLeft size={16} />
            </button>
            <h2>{MONTH_NAMES[month]} {year}</h2>
            <button className="icon-btn" onClick={() => setMonthCursor(new Date(year, month + 1, 1))}>
              <ChevronRight size={16} />
            </button>
          </div>
          <div className="view-toggle">
            <button className={!calListView ? "toggle-btn active" : "toggle-btn"} onClick={() => setCalListView(false)}>
              <LayoutGrid size={13} /> Calendar
            </button>
            <button className={calListView ? "toggle-btn active" : "toggle-btn"} onClick={() => setCalListView(true)}>
              <ListIcon size={13} /> List
            </button>
          </div>
        </div>

        {!calListView ? (
          <>
            <div className="cal-grid cal-dow">
              {["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map((d) => <div key={d} className="cal-dow-cell">{d}</div>)}
            </div>
            <div className="cal-grid">
              {cells.map((d, i) => {
                if (!d) return <div key={i} className="cal-cell cal-empty" />;
                const found = dayClients(d);
                const hasVip = found.some((c) => c.vip);
                return (
                  <button
                    key={i}
                    className={`cal-cell ${isToday(d) ? "cal-today" : ""} ${calSelectedDay === d ? "cal-selected" : ""}`}
                    onClick={() => setCalSelectedDay(d)}
                  >
                    <span className="cal-daynum">{d}</span>
                    {found.length > 0 && (
                      <span className={`cal-dot ${hasVip ? "cal-dot-vip" : ""}`} />
                    )}
                  </button>
                );
              })}
            </div>
            {calSelectedDay && (
              <div className="cal-daylist">
                <h3>{MONTH_NAMES[month]} {calSelectedDay} — {dayClients(calSelectedDay).length} birthday(s)</h3>
                {dayClients(calSelectedDay).length ? (
                  renderMonthTable(
                    dayClients(calSelectedDay).map((c) => ({ ...c, days: daysUntilBirthday(c.dob) }))
                  )
                ) : (
                  <p className="empty-state">No clients celebrate on this date.</p>
                )}
              </div>
            )}
          </>
        ) : (
          <div className="table-scroll">
            {renderMonthTable(
              branchFiltered
                .filter((c) => parseDob(c.dob).month === month + 1)
                .sort((a, b) => parseDob(a.dob).day - parseDob(b.dob).day)
            )}
          </div>
        )}
      </div>
    );
  }

  /* ---- reports ---- */
  function ReportCard({ label, count, accent, rows }) {
    return (
      <div className="report-card" style={{ borderLeftColor: accent }}>
        <div className="report-head">
          <span className="report-count" style={{ color: accent }}>{count}</span>
          <span className="report-label">{label}</span>
        </div>
        <div className="report-export">
          <button className="btn btn-outline btn-sm" onClick={() => showToast(`${label} exported as Excel`)}>
            <Download size={13} /> Excel
          </button>
          <button className="btn btn-outline btn-sm" onClick={() => showToast(`${label} exported as CSV`)}>
            <Download size={13} /> CSV
          </button>
          <button className="btn btn-outline btn-sm" onClick={() => showToast(`${label} exported as PDF`)}>
            <Download size={13} /> PDF
          </button>
        </div>
      </div>
    );
  }

  function renderReports() {
    return (
      <div className="panel">
        <div className="panel-head"><h2>Reports</h2><p className="panel-sub">Export birthday lists by period</p></div>
        <div className="report-grid">
          <ReportCard label="Today's Birthdays" count={today.length} accent="#D46A4A" />
          <ReportCard label="Tomorrow's Birthdays" count={tomorrow.length} accent="#4A7C59" />
          <ReportCard label="This Week's Birthdays" count={thisWeek.length} accent="#C89B5E" />
          <ReportCard label="Next Week's Birthdays" count={nextWeek.length} accent="#B5651D" />
        </div>
      </div>
    );
  }

  /* ---- add client modal ---- */
  function AddClientModal() {
    const [form, setForm] = useState({
      name: "", mobile: "", whatsapp: "", email: "", dob: "", gender: "Female",
      city: "", membership: "Silver", branch: "Agra", anniversary: "", notes: "",
    });
    function set(k, v) { setForm((f) => ({ ...f, [k]: v })); }
    async function submit() {
      if (!form.name || !form.dob) { showToast("Full name and date of birth are required"); return; }
      try {
        const res = await fetch("/api/clients", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(form),
        });
        if (!res.ok) throw new Error();
        await fetchClients();
        showToast(`${form.name} added to client records`);
        setModalOpen(false);
      } catch (e) {
        showToast("Could not save client — check your Supabase connection");
      }
    }
    return (
      <div className="modal-backdrop" onClick={() => setModalOpen(false)}>
        <div className="modal" onClick={(e) => e.stopPropagation()}>
          <div className="modal-head">
            <h2>Add Client</h2>
            <button className="icon-btn" onClick={() => setModalOpen(false)}><X size={17} /></button>
          </div>
          <div className="modal-body">
            <div className="form-grid">
              <label>Full Name<input value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="e.g. Ananya Rao" /></label>
              <label>Mobile Number<input value={form.mobile} onChange={(e) => set("mobile", e.target.value)} placeholder="+91" /></label>
              <label>WhatsApp Number<input value={form.whatsapp} onChange={(e) => set("whatsapp", e.target.value)} placeholder="+91" /></label>
              <label>Email Address<input value={form.email} onChange={(e) => set("email", e.target.value)} placeholder="name@email.com" /></label>
              <label>Date Of Birth<input type="date" value={form.dob} onChange={(e) => set("dob", e.target.value)} /></label>
              <label>Gender
                <select value={form.gender} onChange={(e) => set("gender", e.target.value)}>
                  <option>Female</option><option>Male</option><option>Other</option>
                </select>
              </label>
              <label>City<input value={form.city} onChange={(e) => set("city", e.target.value)} placeholder="e.g. Agra" /></label>
              <label>Membership Type
                <select value={form.membership} onChange={(e) => set("membership", e.target.value)}>
                  <option>Silver</option><option>Gold</option><option>Platinum</option>
                </select>
              </label>
              <label>Branch
                <select value={form.branch} onChange={(e) => set("branch", e.target.value)}>
                  <option>Agra</option><option>Gwalior</option><option>Jaipur</option>
                </select>
              </label>
              <label>Anniversary Date<input type="date" value={form.anniversary} onChange={(e) => set("anniversary", e.target.value)} /></label>
              <label className="full-span">Notes<textarea rows={3} value={form.notes} onChange={(e) => set("notes", e.target.value)} placeholder="Preferences, allergies, occasion notes…" /></label>
            </div>
          </div>
          <div className="modal-foot">
            <button className="btn btn-outline" onClick={() => setModalOpen(false)}>Cancel</button>
            <button className="btn btn-gold" onClick={submit}>Save Client</button>
          </div>
        </div>
      </div>
    );
  }

  function renderClientsView() {
    return (
      <div className="panel">
        <div className="panel-head clients-head">
          <div><h2>All Clients</h2><p className="panel-sub">{tableClients.length} of {branchFiltered.length} clients</p></div>
          <button className="btn btn-gold" onClick={() => setModalOpen(true)}><Plus size={15} /> Add Client</button>
        </div>
        <div className="filters-row">
          <div className="search-mini">
            <Search size={14} />
            <input placeholder="Search name, phone, email or ID…" value={tableSearch} onChange={(e) => setTableSearch(e.target.value)} />
          </div>
          <select value={filterMembership} onChange={(e) => setFilterMembership(e.target.value)}>
            <option value="All">All Memberships</option><option>Platinum</option><option>Gold</option><option>Silver</option>
          </select>
          <select value={filterVip} onChange={(e) => setFilterVip(e.target.value)}>
            <option value="All">All Clients</option><option value="VIP">VIP Only</option><option value="Non-VIP">Non-VIP</option>
          </select>
          <select value={filterMonth} onChange={(e) => setFilterMonth(e.target.value)}>
            <option value="All">All Months</option>
            {MONTH_NAMES.map((m) => <option key={m}>{m}</option>)}
          </select>
        </div>
        <div className="table-scroll">
          {tableClients.length ? renderClientsTable(tableClients) : <div className="empty-state">No clients match these filters.</div>}
        </div>
      </div>
    );
  }

  let content;
  if (view === "overview") content = renderOverview();
  else if (view === "today") content = <TableShell title="Today's Birthdays" empty="No birthdays today.">{today.length ? renderTodayTable(today) : null}</TableShell>;
  else if (view === "tomorrow") content = <TableShell title="Tomorrow's Birthdays" empty="No birthdays tomorrow.">{tomorrow.length ? renderTomorrowTable(tomorrow) : null}</TableShell>;
  else if (view === "next3") content = <TableShell title="Next 3 Days" subtitle="Birthdays within the next 3 days" empty="No birthdays in this range.">{next3.length ? renderDaysRemainingTable(next3) : null}</TableShell>;
  else if (view === "week") content = <TableShell title="This Week" subtitle="Birthdays within the next 7 days" empty="No birthdays this week.">{thisWeek.length ? renderWeekTable(thisWeek) : null}</TableShell>;
  else if (view === "nextweek") content = <TableShell title="Next Week" subtitle="Birthdays 8–14 days from today" empty="No birthdays next week.">{nextWeek.length ? renderWeekTable(nextWeek) : null}</TableShell>;
  else if (view === "month") content = <TableShell title="This Month" subtitle={`Remaining birthdays in ${MONTH_NAMES[TODAY.getMonth()]}`} empty="No remaining birthdays this month.">{thisMonth.length ? renderMonthTable(thisMonth) : null}</TableShell>;
  else if (view === "vip") content = <TableShell title="VIP Clients" subtitle="Sorted by nearest birthday" empty="No VIP clients on record.">{vipClients.length ? renderVipTable(vipClients) : null}</TableShell>;
  else if (view === "clients") content = renderClientsView();
  else if (view === "calendar") content = renderCalendar();
  else if (view === "reports") content = renderReports();

  return (
    <div className="oranz-app">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&family=Inter:wght@400;500;600&display=swap');

        .oranz-app {
          --bg:#FFFFFF; --bg-secondary:#FAF8F4; --border:#E8DFD3; --gold:#C89B5E;
          --gold-deep:#A87F49; --text:#2B2B2B; --text-secondary:#6F6F6F;
          --success:#4A7C59; --alert:#D46A4A;
          font-family:'Inter',sans-serif; color:var(--text); background:var(--bg-secondary);
          min-height:100vh; display:flex; font-size:14px; position:relative;
        }
        .oranz-app * { box-sizing:border-box; }
        .oranz-app h1,.oranz-app h2,.oranz-app h3 { font-family:'Playfair Display',serif; font-weight:600; margin:0; color:var(--text); }
        .oranz-app button { font-family:'Inter',sans-serif; font-weight:500; cursor:pointer; }
        .oranz-app input, .oranz-app select, .oranz-app textarea { font-family:'Inter',sans-serif; }

        /* Sidebar */
        .sidebar { width:222px; flex-shrink:0; background:var(--gold); border-right:1px solid var(--gold-deep); padding:24px 14px; display:flex; flex-direction:column; gap:26px; }
        .brand { padding:0 10px; }
        .brand-name { font-family:'Playfair Display',serif; font-size:21px; letter-spacing:0.5px; color:#2B2B2B; }
        .brand-name span { color:#FFFFFF; }
        .brand-sub { font-size:10.5px; letter-spacing:2px; color:rgba(43,43,43,0.7); text-transform:uppercase; margin-top:2px; }
        .brand-logo { width:100%; max-width:150px; height:auto; display:block; margin:0 auto; }
        .brand-logo-wrap { background:#FFFFFF; border:1px solid rgba(43,43,43,0.12); border-radius:10px; padding:14px 10px 10px; box-shadow:0 2px 8px rgba(43,43,43,0.08); }
        .nav-list { display:flex; flex-direction:column; gap:2px; }
        .nav-item { display:flex; align-items:center; justify-content:space-between; padding:9px 12px; border-radius:6px; border:none; background:transparent; color:#2B2B2B; font-size:13.5px; text-align:left; transition:background .15s, color .15s; border-left:2px solid transparent; }
        .nav-item:hover { background:rgba(255,255,255,0.28); color:#2B2B2B; }
        .nav-item.active { background:#2B2B2B; color:#fff; border-left:2px solid #FFFFFF; font-weight:600; }
        .nav-count { font-size:11px; color:#2B2B2B; background:rgba(255,255,255,0.5); border:1px solid rgba(43,43,43,0.25); border-radius:20px; padding:1px 7px; }
        .nav-item.active .nav-count { color:#fff; background:rgba(255,255,255,0.18); border-color:rgba(255,255,255,0.4); }

        /* Header */
        .main { flex:1; display:flex; flex-direction:column; min-width:0; }
        .topbar { height:66px; background:var(--bg); border-bottom:1px solid var(--border); display:flex; align-items:center; justify-content:space-between; padding:0 28px; gap:20px; }
        .search-wrap { position:relative; flex:1; max-width:380px; }
        .search-box { display:flex; align-items:center; gap:8px; background:var(--bg-secondary); border:1px solid var(--border); border-radius:7px; padding:8px 12px; color:var(--text-secondary); }
        .search-box input { border:none; background:transparent; outline:none; width:100%; font-size:13.5px; color:var(--text); }
        .search-dropdown { position:absolute; top:calc(100% + 6px); left:0; right:0; background:var(--bg); border:1px solid var(--border); border-radius:8px; box-shadow:0 8px 24px rgba(43,43,43,0.08); z-index:20; overflow:hidden; }
        .search-dropdown-item { padding:9px 14px; font-size:13px; border-bottom:1px solid var(--border); display:flex; justify-content:space-between; }
        .search-dropdown-item:last-child { border-bottom:none; }
        .topbar-right { display:flex; align-items:center; gap:16px; }
        .branch-select { display:flex; align-items:center; gap:6px; border:1px solid var(--border); border-radius:7px; padding:8px 12px; font-size:13px; background:var(--bg); color:var(--text); }
        .branch-select select { border:none; background:transparent; outline:none; font-size:13px; color:var(--text); }
        .bell-wrap { position:relative; }
        .bell-btn { position:relative; border:1px solid var(--border); background:var(--bg); border-radius:7px; padding:8px; display:flex; }
        .bell-dot { position:absolute; top:5px; right:5px; width:7px; height:7px; border-radius:50%; background:var(--alert); border:1.5px solid var(--bg); }
        .notif-dropdown { position:absolute; right:0; top:calc(100% + 8px); width:280px; background:var(--bg); border:1px solid var(--border); border-radius:8px; box-shadow:0 8px 24px rgba(43,43,43,0.08); z-index:30; }
        .notif-dropdown h4 { padding:12px 14px; margin:0; font-family:'Inter'; font-size:12px; text-transform:uppercase; letter-spacing:1px; color:var(--text-secondary); border-bottom:1px solid var(--border); }
        .notif-item { padding:10px 14px; font-size:13px; border-bottom:1px solid var(--border); display:flex; justify-content:space-between; }
        .notif-item:last-child { border-bottom:none; }
        .notif-item .n-count { color:var(--gold-deep); font-weight:600; }
        .profile { display:flex; align-items:center; gap:9px; }
        .profile-avatar { width:34px; height:34px; border-radius:50%; background:var(--gold); color:#fff; display:flex; align-items:center; justify-content:center; font-size:12.5px; font-weight:600; }
        .profile-name { font-size:13px; font-weight:600; line-height:1.1; }
        .profile-role { font-size:11px; color:var(--text-secondary); }

        .content { padding:26px 30px 50px; flex:1; overflow-y:auto; }

        /* KPI */
        .kpi-grid { display:grid; grid-template-columns:repeat(5,1fr); gap:14px; margin-bottom:22px; }
        .kpi-card { position:relative; background:var(--bg); border:1px solid var(--border); border-top:2.5px solid var(--border); border-radius:9px; padding:18px 18px 16px; transition:box-shadow .2s, transform .15s; text-align:left; width:100%; }
        .kpi-clickable { cursor:pointer; }
        .kpi-clickable:hover { border-color:var(--gold); box-shadow:0 4px 14px rgba(43,43,43,0.08); transform:translateY(-1px); }
        .kpi-clickable:active { transform:translateY(0); }
        .kpi-clickable:focus-visible { outline:2px solid var(--gold); outline-offset:2px; }
        .kpi-bold { border-width:1.5px; border-top-width:3px; box-shadow:0 3px 10px rgba(43,43,43,0.06); }
        .kpi-bold .kpi-value { font-weight:700; }
        .kpi-value { font-family:'Playfair Display',serif; font-size:28px; color:var(--text); }
        .kpi-label { font-size:12px; color:var(--text-secondary); margin-top:4px; }
        .kpi-live-dot { position:absolute; top:14px; right:14px; width:7px; height:7px; border-radius:50%; animation:kpi-blink 1.8s ease-in-out infinite; }
        .kpi-pulse { animation:kpi-glow 1.8s ease-in-out infinite; }
        @keyframes kpi-blink { 0%,100% { opacity:1; } 50% { opacity:0.25; } }
        @keyframes kpi-glow {
          0%,100% { box-shadow:0 0 0 rgba(0,0,0,0); }
          50% { box-shadow:0 0 0 4px rgba(200,155,94,0.06); }
        }
        @media (prefers-reduced-motion: reduce) {
          .kpi-live-dot, .kpi-pulse { animation:none; }
        }

        .quick-actions { display:flex; gap:10px; margin-bottom:26px; flex-wrap:wrap; }
        .btn { display:inline-flex; align-items:center; gap:6px; border-radius:7px; padding:9px 16px; font-size:13px; border:1px solid transparent; }
        .btn-sm { padding:6px 11px; font-size:12px; }
        .btn-gold { background:var(--gold); color:#fff; }
        .btn-gold:hover { background:var(--gold-deep); }
        .btn-outline { background:var(--bg); border:1px solid var(--border); color:var(--text); }
        .btn-outline:hover { border-color:var(--gold); color:var(--gold-deep); }

        /* Panel / table */
        .panel { background:var(--bg); border:1px solid var(--border); border-radius:10px; padding:22px 22px 8px; margin-bottom:22px; }
        .panel-head { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:14px; }
        .panel-sub { font-size:12.5px; color:var(--text-secondary); margin-top:3px; }
        .table-scroll { overflow-x:auto; }
        table { width:100%; border-collapse:collapse; font-size:13px; }
        thead th { text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:0.6px; color:var(--text-secondary); font-weight:600; padding:10px 12px; border-bottom:1px solid var(--border); white-space:nowrap; }
        th.sortable { cursor:pointer; user-select:none; }
        th.sortable span { vertical-align:middle; }
        tbody td { padding:12px; border-bottom:1px solid var(--border); vertical-align:middle; white-space:nowrap; }
        tbody tr:hover { background:var(--bg-secondary); }
        tbody tr.vip-row { border-left:3px solid var(--gold); background:linear-gradient(90deg, rgba(200,155,94,0.06), transparent 60%); }
        .client-cell { display:flex; align-items:center; gap:10px; font-weight:500; }
        .avatar { width:30px; height:30px; border-radius:50%; background:var(--bg-secondary); border:1px solid var(--border); display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:600; color:var(--gold-deep); flex-shrink:0; }
        .avatar-gold { background:var(--gold); color:#fff; border-color:var(--gold); }
        .mono { font-family:'Inter'; font-size:12.5px; color:var(--text-secondary); }
        .muted { color:var(--text-secondary); }
        .action-row { display:flex; gap:6px; }
        .icon-btn { border:1px solid var(--border); background:var(--bg); border-radius:6px; padding:6px; display:flex; align-items:center; justify-content:center; color:var(--text-secondary); }
        .icon-btn:hover { border-color:var(--gold); color:var(--gold-deep); }
        .vip-badge { font-size:9.5px; letter-spacing:0.6px; border:1px solid var(--gold); color:var(--gold-deep); border-radius:20px; padding:1px 7px; margin-left:8px; font-weight:600; }
        .tag { font-size:11px; padding:3px 9px; border-radius:20px; border:1px solid var(--border); font-weight:500; }
        .tag-platinum { border-color:#C9CDD6; color:#5A6270; background:#F4F5F7; }
        .tag-gold { border-color:var(--gold); color:var(--gold-deep); background:#FBF4E9; }
        .tag-silver { border-color:#D8D8D8; color:#7A7A7A; background:#F7F7F7; }
        .status-dot { font-size:11.5px; padding-left:14px; position:relative; }
        .status-dot::before { content:''; position:absolute; left:0; top:50%; transform:translateY(-50%); width:6px; height:6px; border-radius:50%; }
        .status-active::before { background:var(--success); }
        .status-inactive::before { background:var(--text-secondary); }
        .days-badge { display:inline-flex; align-items:center; justify-content:center; width:30px; height:30px; border-radius:50%; border:1.4px solid var(--gold); font-family:'Playfair Display',serif; font-size:13px; color:var(--gold-deep); }
        .empty-state { padding:34px 0; text-align:center; color:var(--text-secondary); font-size:13.5px; }

        /* Clients view filters */
        .clients-head { align-items:center; }
        .filters-row { display:flex; gap:10px; margin-bottom:16px; flex-wrap:wrap; }
        .search-mini { display:flex; align-items:center; gap:7px; background:var(--bg-secondary); border:1px solid var(--border); border-radius:7px; padding:8px 12px; flex:1; min-width:220px; color:var(--text-secondary); }
        .search-mini input { border:none; background:transparent; outline:none; width:100%; font-size:13px; color:var(--text); }
        .filters-row select { border:1px solid var(--border); border-radius:7px; padding:8px 10px; font-size:12.5px; background:var(--bg); color:var(--text); }

        /* Calendar */
        .cal-head { align-items:center; }
        .cal-nav { display:flex; align-items:center; gap:12px; }
        .view-toggle { display:flex; border:1px solid var(--border); border-radius:7px; overflow:hidden; }
        .toggle-btn { display:flex; align-items:center; gap:6px; padding:7px 13px; font-size:12.5px; background:var(--bg); border:none; color:var(--text-secondary); }
        .toggle-btn.active { background:var(--bg-secondary); color:var(--gold-deep); font-weight:600; }
        .cal-grid { display:grid; grid-template-columns:repeat(7,1fr); gap:6px; margin-top:14px; }
        .cal-dow-cell { text-align:center; font-size:11px; color:var(--text-secondary); text-transform:uppercase; letter-spacing:0.5px; padding-bottom:4px; }
        .cal-cell { aspect-ratio:1; border:1px solid var(--border); border-radius:8px; background:var(--bg); display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; color:var(--text); position:relative; }
        .cal-cell:hover { border-color:var(--gold); }
        .cal-empty { border:none; background:transparent; }
        .cal-daynum { font-size:13px; }
        .cal-today { background:var(--bg-secondary); border-color:var(--gold); font-weight:600; }
        .cal-selected { outline:1.5px solid var(--gold); }
        .cal-dot { width:5px; height:5px; border-radius:50%; background:var(--gold); }
        .cal-dot-vip { background:var(--alert); }
        .cal-daylist { margin-top:22px; border-top:1px solid var(--border); padding-top:16px; }
        .cal-daylist h3 { font-size:15px; margin-bottom:10px; }

        /* Reports */
        .report-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:14px; margin-top:6px; margin-bottom:20px; }
        .report-card { background:var(--bg-secondary); border:1px solid var(--border); border-left:3px solid var(--gold); border-radius:9px; padding:16px; }
        .report-head { display:flex; flex-direction:column; margin-bottom:14px; }
        .report-count { font-family:'Playfair Display',serif; font-size:26px; }
        .report-label { font-size:12.5px; color:var(--text-secondary); margin-top:2px; }
        .report-export { display:flex; gap:6px; flex-wrap:wrap; }

        /* Modal */
        .modal-backdrop { position:fixed; inset:0; background:rgba(43,43,43,0.35); display:flex; align-items:center; justify-content:center; z-index:100; }
        .modal { background:var(--bg); width:560px; max-width:92vw; max-height:86vh; border-radius:10px; overflow:hidden; display:flex; flex-direction:column; box-shadow:0 20px 50px rgba(0,0,0,0.2); }
        .modal-head { display:flex; justify-content:space-between; align-items:center; padding:18px 22px; border-bottom:1px solid var(--border); }
        .modal-body { padding:20px 22px; overflow-y:auto; }
        .form-grid { display:grid; grid-template-columns:1fr 1fr; gap:14px 16px; }
        .form-grid label { display:flex; flex-direction:column; gap:6px; font-size:12.5px; color:var(--text-secondary); }
        .form-grid .full-span { grid-column:1 / -1; }
        .form-grid input, .form-grid select, .form-grid textarea { border:1px solid var(--border); border-radius:7px; padding:9px 11px; font-size:13px; color:var(--text); outline:none; background:var(--bg); }
        .form-grid input:focus, .form-grid select:focus, .form-grid textarea:focus { border-color:var(--gold); }
        .modal-foot { display:flex; justify-content:flex-end; gap:10px; padding:16px 22px; border-top:1px solid var(--border); }

        /* Toast */
        .toast { position:fixed; bottom:26px; left:50%; transform:translateX(-50%); background:var(--text); color:#fff; padding:11px 20px; border-radius:8px; font-size:13px; z-index:200; box-shadow:0 10px 30px rgba(0,0,0,0.25); }

        @media (max-width: 980px) {
          .kpi-grid { grid-template-columns:repeat(2,1fr); }
          .report-grid { grid-template-columns:repeat(2,1fr); }
          .sidebar { width:180px; }
        }
      `}</style>

      <aside className="sidebar">
        <div className="brand">
          <div className="brand-logo-wrap">
            <img src={LOGO_DATA_URI} alt="Oranz Body Spa" className="brand-logo" />
          </div>
        </div>
        <nav className="nav-list">
          {navItems.map((n) => (
            <button key={n.key} className={`nav-item ${view === n.key ? "active" : ""}`} onClick={() => { setView(n.key); setCalSelectedDay(null); }}>
              <span>{n.label}</span>
              {typeof n.count === "number" && <span className="nav-count">{n.count}</span>}
            </button>
          ))}
        </nav>
      </aside>

      <div className="main">
        <header className="topbar">
          <div className="search-wrap">
            <div className="search-box">
              <Search size={15} />
              <input placeholder="Search clients by name, phone or ID…" value={globalSearch} onChange={(e) => setGlobalSearch(e.target.value)} />
            </div>
            {globalHits.length > 0 && (
              <div className="search-dropdown">
                {globalHits.map((c) => (
                  <div key={c.id} className="search-dropdown-item">
                    <span>{c.name}</span><span className="muted">{c.phone}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div className="topbar-right">
            <div className="branch-select">
              <select value={branch} onChange={(e) => setBranch(e.target.value)}>
                <option>All Branches</option><option>Agra</option><option>Gwalior</option><option>Jaipur</option>
              </select>
              <ChevronDown size={13} />
            </div>
            <div className="bell-wrap">
              <button className="bell-btn" onClick={() => setNotifOpen((o) => !o)}>
                <Bell size={17} />
                {(today.length + tomorrow.length) > 0 && <span className="bell-dot" />}
              </button>
              {notifOpen && (
                <div className="notif-dropdown">
                  <h4>Notifications</h4>
                  <div className="notif-item"><span>Birthday Today</span><span className="n-count">{today.length}</span></div>
                  <div className="notif-item"><span>Birthday Tomorrow</span><span className="n-count">{tomorrow.length}</span></div>
                  <div className="notif-item"><span>Birthday In 3 Days</span><span className="n-count">{next3.length}</span></div>
                  <div className="notif-item"><span>Birthday This Week</span><span className="n-count">{thisWeek.length}</span></div>
                </div>
              )}
            </div>
            <div className="profile">
              <span className="profile-avatar">AD</span>
              <div>
                <div className="profile-name">Admin</div>
                <div className="profile-role">Front Desk Manager</div>
              </div>
            </div>
          </div>
        </header>

        <main className="content">{loading ? <div className="panel">Loading clients…</div> : content}</main>
      </div>

      {modalOpen && <AddClientModal />}
      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}
